const stories={

cortex:`<p class="eyebrow">01 / AI & COLLABORATION · TEAM PROJECT</p><h2>Cortex</h2><p>AI works better when it understands the whole team. Cortex connects departmental context in a shared workspace, helping conversations build on decisions made elsewhere.</p><h3>THE EXPERIENCE</h3><p>A chat interface pairs with a visual context map. Department memory and connected tools help preserve useful decisions and make them available across the organization.</p><h3>BUILT TOGETHER</h3><p>Created for SOON Hackathon with Aman Shah, Cris Huynh, and JusByte.</p><div class="tags"><span>Next.js</span><span>TypeScript</span><span>Claude</span><span>Backboard</span><span>Composio</span><span>Cloudinary</span></div><div class="modal-links"><a href="https://devpost.com/software/cortex-yv9awn" target="_blank" rel="noopener noreferrer">Project story </a><a href="https://github.com/aman-a-shah/cortex" target="_blank" rel="noopener noreferrer">Source code </a><a href="https://www.youtube.com/watch?v=Z6-UdrfkAlE" target="_blank" rel="noopener noreferrer">Watch demo </a></div>`,

invest:`<p class="eyebrow">02 / EDUCATION & FINTECH · TEAM PROJECT</p><h2>altF4 invest</h2><p>Investing can feel overwhelming before you even begin. altF4 invest combines short lessons with market simulation, creating a place to learn and practice.</p><h3>THE EXPERIENCE</h3><p>A learning dashboard brings together lessons, progress, XP, and streaks. Portfolio and strategy features connect the concepts to hands-on exploration.</p><h3>BUILT TOGETHER</h3><p>Created with Ayushmaan Roy for WinHacks 2026. Supabase supports authentication and saved progress.</p><div class="tags"><span>Next.js</span><span>React</span><span>TypeScript</span><span>Supabase</span><span>Tailwind CSS</span></div><div class="modal-links"><a href="https://uwinhacks-altf4.vercel.app" target="_blank" rel="noopener noreferrer">Visit project </a><a href="https://github.com/HaydenLongerich/uwinhacks-altf4" target="_blank" rel="noopener noreferrer">Source code </a><a href="https://devpost.com/software/alt-f4-invest" target="_blank" rel="noopener noreferrer">Project story </a></div>`,

overview:`<p class="eyebrow">PORTFOLIO</p><h2>Hayden Longerich</h2><p>Hey I'm Hayden, A Software Engineer studying at the University of Windsor. I love building things, from LEGO models to software. I’m curious about how things work and enjoy turning ideas into reality and figuring out ways to improve efficiency.</p><p>I’ve worked on projects like Cortex, a shared-context AI workspace for teams, and altF4 invest, an investing education and simulation platform, LEGO collection databases and many more.</p><p>Feel free to reach out for a chat!</p><div class="modal-links"><a href="https://github.com/HaydenLongerich" target="_blank" rel="noopener noreferrer">GitHub </a><a href="https://www.linkedin.com/in/hayden-longerich/" target="_blank" rel="noopener noreferrer">LinkedIn </a><a href="contact.html">Contact </a></div>`};

const modal=document.querySelector('#modal');let trigger;

document.querySelectorAll('[data-dialog]').forEach(b=>b.addEventListener('click',()=>{if(!Object.hasOwn(stories,b.dataset.dialog))return;trigger=b;document.querySelector('#modalContent').innerHTML=stories[b.dataset.dialog];modal.showModal();document.body.style.overflow='hidden'}));

document.querySelector('#closeModal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});modal.addEventListener('close',()=>{document.body.style.overflow='';trigger?.focus()});

